import { describe, test, expect, beforeAll } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'
import { User } from '../app/Models/User.js'
import { Post } from '../app/Models/Post.js'

describe('PostController with scheduling', () => {
  let http: TestApp
  let user: any
  let otherUser: any

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
    user = await User.create({
      name: 'Test User',
      email: 'test@example.com',
      password: 'password123',
    })
    otherUser = await User.create({
      name: 'Other User',
      email: 'other@example.com',
      password: 'password123',
    })
  })

  test('creates a post with no publish date', async () => {
    const csrf = await http.actingAs(user).withCsrf()
    const res = await csrf.post('/posts', {
      title: 'Public Post',
      excerpt: 'This is public',
      body: 'Content',
    })
    expect(res.status).toBe(303)
  })

  test('creates a post with a future publish date', async () => {
    const csrf = await http.actingAs(user).withCsrf()
    const futureDate = new Date(Date.now() + 86400000).toISOString()
    const res = await csrf.post('/posts', {
      title: 'Scheduled Post',
      excerpt: 'This is scheduled',
      body: 'Content',
      publishAt: futureDate,
    })
    expect(res.status).toBe(303)
  })

  test('scheduled post is hidden from other users in list', async () => {
    const res = await http.get('/posts')
    const posts = await res.json<any>()
    const scheduledPost = posts.data.find((p: any) => p.title === 'Scheduled Post')
    expect(scheduledPost).toBeUndefined()
  })

  test('scheduled post is visible to author in list', async () => {
    const res = await http.actingAs(user).get('/posts')
    const posts = await res.json<any>()
    const scheduledPost = posts.data.find((p: any) => p.title === 'Scheduled Post')
    expect(scheduledPost).toBeDefined()
    expect(scheduledPost.publishedAt).toBeTruthy()
  })

  test('scheduled post returns 403 for other users', async () => {
    const posts = await Post.where('title', 'Scheduled Post').get()
    const scheduledPost = posts[0]

    const res = await http.actingAs(otherUser).get(`/posts/${scheduledPost.id}`)
    expect(res.status).toBe(403)
  })

  test('scheduled post is visible to author', async () => {
    const posts = await Post.where('title', 'Scheduled Post').get()
    const scheduledPost = posts[0]

    const res = await http.actingAs(user).get(`/posts/${scheduledPost.id}`)
    expect(res.status).toBe(200)
    const data = await res.json<any>()
    expect(data.post.publishedAt).toBeTruthy()
  })

  test('scheduled post is hidden from search for other users', async () => {
    const res = await http.query('/posts/search', {
      keywords: ['Scheduled'],
      limit: 10,
    })
    const posts = await res.json<any>()
    expect(posts.data.length).toBe(0)
  })

  test('scheduled post is visible in search for author', async () => {
    const res = await http.actingAs(user).query('/posts/search', {
      keywords: ['Scheduled'],
      limit: 10,
    })
    const posts = await res.json<any>()
    expect(posts.data.length).toBe(1)
    expect(posts.data[0].title).toBe('Scheduled Post')
  })

  test('console command lists scheduled posts', async () => {
    const futureDate = new Date(Date.now() + 86400000).toISOString()
    const post = await Post.forceCreate({
      title: 'Console Test Post',
      excerpt: 'Test',
      body: 'Content',
      authorId: user.id,
      publishedAt: futureDate,
    })

    const { execSync } = require('child_process')
    const output = execSync('bun run console posts:scheduled', {
      cwd: process.cwd(),
      encoding: 'utf-8',
    })

    expect(output).toContain(`${post.id}\tConsole Test Post\t${futureDate}`)
  })

  test('console command does not list public posts', async () => {
    const { execSync } = require('child_process')
    const output = execSync('bun run console posts:scheduled', {
      cwd: process.cwd(),
      encoding: 'utf-8',
    })

    expect(output).not.toContain('Public Post')
  })

  test('published post is visible to everyone after date passes', async () => {
    const pastDate = new Date(Date.now() - 1000).toISOString()
    const post = await Post.forceCreate({
      title: 'Published Post',
      excerpt: 'Now public',
      body: 'Content',
      authorId: user.id,
      publishedAt: pastDate,
    })

    const res = await http.get(`/posts/${post.id}`)
    expect(res.status).toBe(200)

    const listRes = await http.get('/posts')
    const posts = await listRes.json<any>()
    const foundPost = posts.data.find((p: any) => p.id === post.id)
    expect(foundPost).toBeDefined()
  })

  test('author can update a scheduled post', async () => {
    const futureDate = new Date(Date.now() + 86400000).toISOString()
    const post = await Post.forceCreate({
      title: 'Post to Update',
      excerpt: 'Original',
      body: 'Content',
      authorId: user.id,
      publishedAt: futureDate,
    })

    const csrf = await http.actingAs(user).withCsrf()
    const res = await csrf.put(`/posts/${post.id}`, {
      title: 'Updated Title',
      excerpt: 'Updated',
      body: 'New content',
      publishAt: futureDate,
    })
    expect(res.status).toBe(303)

    const updated = await Post.findOrFail(post.id)
    expect(updated.title).toBe('Updated Title')
  })

  test('author can clear publish date to make post public', async () => {
    const futureDate = new Date(Date.now() + 86400000).toISOString()
    const post = await Post.forceCreate({
      title: 'Post to Publish',
      excerpt: 'Scheduled',
      body: 'Content',
      authorId: user.id,
      publishedAt: futureDate,
    })

    const csrf = await http.actingAs(user).withCsrf()
    await csrf.put(`/posts/${post.id}`, {
      title: 'Post to Publish',
      excerpt: 'Scheduled',
      body: 'Content',
      publishAt: null,
    })

    const updated = await Post.findOrFail(post.id)
    expect(updated.publishedAt).toBeNull()

    const res = await http.get(`/posts/${post.id}`)
    expect(res.status).toBe(200)
  })
})
EOF
